CREATE TABLE public.platform_content (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK (kind IN ('story','impact_story','opportunity','event','project','partner','leader','timeline','metric','payment','program','page')), slug text NOT NULL UNIQUE, title text NOT NULL, category text NOT NULL DEFAULT '', excerpt text NOT NULL DEFAULT '', body text NOT NULL DEFAULT '', image_url text, gallery jsonb NOT NULL DEFAULT '[]', details jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','scheduled','archived','closed')), featured boolean NOT NULL DEFAULT false, published_at timestamptz NOT NULL DEFAULT now(), deadline timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.platform_content TO anon, authenticated; GRANT INSERT, UPDATE, DELETE ON public.platform_content TO authenticated; GRANT ALL ON public.platform_content TO service_role;
ALTER TABLE public.platform_content ENABLE ROW LEVEL SECURITY;
CREATE POLICY content_public_read ON public.platform_content FOR SELECT TO anon, authenticated USING (status IN ('published','scheduled','closed') AND published_at <= now());
CREATE POLICY content_admin_all ON public.platform_content FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.engagement_submissions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL, content_id uuid REFERENCES public.platform_content(id) ON DELETE SET NULL, full_name text NOT NULL, email text NOT NULL, payload jsonb NOT NULL DEFAULT '{}', status text NOT NULL DEFAULT 'new' CHECK(status IN ('new','reviewing','accepted','declined','archived')), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE, DELETE ON public.engagement_submissions TO authenticated; GRANT ALL ON public.engagement_submissions TO service_role;
ALTER TABLE public.engagement_submissions ENABLE ROW LEVEL SECURITY;
CREATE POLICY submissions_admin ON public.engagement_submissions FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.platform_subscribers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, full_name text NOT NULL DEFAULT '', categories jsonb NOT NULL DEFAULT '[]', unsubscribe_token uuid NOT NULL DEFAULT gen_random_uuid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE, DELETE ON public.platform_subscribers TO authenticated; GRANT ALL ON public.platform_subscribers TO service_role;
ALTER TABLE public.platform_subscribers ENABLE ROW LEVEL SECURITY;
CREATE POLICY subscriber_admin ON public.platform_subscribers FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.submit_engagement(_kind text, _name text, _email text, _payload jsonb, _content_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result uuid; item public.platform_content; BEGIN
IF _kind NOT IN ('volunteer','membership','partnership','skills','support','in_kind','contact','story','application','event') THEN RAISE EXCEPTION 'Invalid submission type'; END IF;
IF length(trim(_name)) < 2 OR length(_name)>200 OR _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(_email)>254 OR octet_length(_payload::text)>50000 THEN RAISE EXCEPTION 'Please check your name, email and message'; END IF;
IF coalesce((_payload->>'consent')::boolean,false)=false THEN RAISE EXCEPTION 'Consent is required'; END IF;
PERFORM pg_advisory_xact_lock(hashtext(lower(trim(_email))));
IF EXISTS(SELECT 1 FROM public.engagement_submissions WHERE email=lower(trim(_email)) AND created_at>now()-interval '30 seconds') THEN RAISE EXCEPTION 'Please wait a moment before sending another submission'; END IF;
IF _kind IN ('application','event') THEN SELECT * INTO item FROM public.platform_content WHERE id=_content_id AND status IN ('published','scheduled') AND published_at<=now(); IF item.id IS NULL OR (item.deadline IS NOT NULL AND item.deadline<=now()) OR (_kind='application' AND item.kind<>'opportunity') OR (_kind='event' AND item.kind<>'event') THEN RAISE EXCEPTION 'This call is no longer accepting submissions'; END IF; END IF;
INSERT INTO public.engagement_submissions(kind,full_name,email,payload,content_id) VALUES(_kind,trim(_name),lower(trim(_email)),_payload,_content_id) RETURNING id INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.submit_engagement(text,text,text,jsonb,uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.submit_engagement(text,text,text,jsonb,uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.subscribe_platform(_email text,_name text DEFAULT '',_categories jsonb DEFAULT '[]') RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE token uuid; BEGIN IF _email !~ '^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$' OR length(_email)>254 OR length(_name)>200 OR octet_length(_categories::text)>2000 THEN RAISE EXCEPTION 'Please check your email'; END IF; INSERT INTO public.platform_subscribers(email,full_name,categories) VALUES(lower(trim(_email)),_name,_categories) ON CONFLICT(email) DO UPDATE SET categories=excluded.categories RETURNING unsubscribe_token INTO token; RETURN token; END $$;
REVOKE ALL ON FUNCTION public.subscribe_platform(text,text,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.subscribe_platform(text,text,jsonb) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.unsubscribe_platform(_token uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.platform_subscribers WHERE unsubscribe_token=_token; RETURN FOUND; END $$;
REVOKE ALL ON FUNCTION public.unsubscribe_platform(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.unsubscribe_platform(uuid) TO anon,authenticated;
CREATE OR REPLACE FUNCTION public.verify_member(_member_no text) RETURNS TABLE(full_name text,member_no text,membership_type text,date_joined date) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT m.full_name,m.member_no,m.membership_type,m.date_joined FROM public.members m WHERE m.member_no=_member_no LIMIT 1 $$;
REVOKE ALL ON FUNCTION public.verify_member(text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.verify_member(text) TO anon,authenticated;
DROP POLICY IF EXISTS "Public can verify members" ON public.members;
GRANT SELECT,INSERT,UPDATE,DELETE ON public.members TO authenticated; GRANT ALL ON public.members TO service_role; GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
CREATE INDEX platform_content_kind ON public.platform_content(kind,status,published_at);
CREATE INDEX engagement_created ON public.engagement_submissions(created_at,email);
CREATE OR REPLACE FUNCTION public.touch_platform_content() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER platform_content_updated BEFORE UPDATE ON public.platform_content FOR EACH ROW EXECUTE FUNCTION public.touch_platform_content();